"""Verified opaque previews for retained Published studies reports.

The application parent opens/downloads only the exact inventoried link targets.
Original scripts never receive the operator origin or its authenticated cookie.
"""
from __future__ import annotations

import hashlib
from html import escape
from html.parser import HTMLParser
import json
from pathlib import Path, PurePosixPath
import posixpath
import re
from urllib.parse import quote, unquote, urlsplit

from delivery_preview import HTML_LIMIT, embed_images
from model.common import describe_file, identifier

VERSION = 1
FOLDER = "published-study-reports"
POLICY = ("sandbox allow-scripts allow-downloads allow-modals allow-popups "
          "allow-popups-to-escape-sandbox; default-src 'none'; "
          "script-src 'unsafe-inline'; style-src 'unsafe-inline'; "
          "img-src data:; connect-src 'none'; object-src 'none'; base-uri 'none'; "
          "form-action 'none'; frame-ancestors 'self'")


def _local(value, member):
    parsed = urlsplit(value)
    if parsed.scheme or parsed.netloc or not parsed.path:
        return None
    path = unquote(parsed.path)
    if (path.startswith("/") or "\\" in path or ":" in path or
            any(ord(c) < 32 or ord(c) == 127 for c in path)):
        raise ValueError("Original report companions must use contained relative paths")
    path = posixpath.normpath(posixpath.join(posixpath.dirname(member), path))
    if path in {".", ".."} or path.startswith("../"):
        raise ValueError("An original report link leaves its retained study")
    return path


class _Companions(HTMLParser):
    def __init__(self, source, member, inventory, read_member):
        super().__init__(convert_charrefs=False)
        self.member, self.inventory, self.read_member = member, inventory, read_member
        self.edits, self.links = [], []
        self.offsets = [0]
        for line in source.split("\n"):
            self.offsets.append(self.offsets[-1] + len(line) + 1)

    def _edit(self, replacement):
        line, column = self.getpos()
        start = self.offsets[line - 1] + column
        self.edits.append((start, start + len(self.get_starttag_text()), replacement))

    def _tag(self, tag, attrs):
        return "<" + tag + "".join(" " + k if v is None else
                                   " " + k + '="' + escape(v, quote=True) + '"'
                                   for k, v in attrs) + ">"

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        first = {}
        for key, value in attrs:
            first.setdefault(key.lower(), value)
        if tag == "base":
            self._edit("")
            return
        if tag == "a" and first.get("href"):
            member = _local(first["href"], self.member)
            if member is None:
                return
            if member not in self.inventory:
                raise ValueError("Original report companion is not retained: " + member)
            parsed = urlsplit(first["href"])
            link_id = str(len(self.links))
            self.links.append({
                "id": link_id, "path": member, "fragment": parsed.fragment,
                "query": parsed.query, "download": "download" in first,
                "html": PurePosixPath(member).suffix.lower() in {".html", ".htm"},
            })
            amended = [(k, v) for k, v in attrs
                       if k.lower() not in {"href", "target", "data-published-member"}]
            amended.extend([("href", "#"), ("data-published-member", link_id)])
            self._edit(self._tag(tag, amended))
        elif tag == "link" and "stylesheet" in (first.get("rel") or "").lower().split():
            if _local(first.get("href") or "", self.member) is not None:
                raise ValueError("This original report needs its separate stylesheet; open the complete study export")
        elif tag == "script" and first.get("src"):
            if _local(first["src"], self.member) is not None:
                raise ValueError("This original report needs separate script files; open the complete study export")

    handle_startendtag = handle_starttag


def _bridge(token):
    # Parent validates the frame Window, this immutable token, and the exact
    # per-preview link inventory. Messages cannot request arbitrary URLs.
    return """<script>
(function(){
  'use strict';
  const token=TOKEN;
  function ready(){parent.postMessage({type:'upstate.published-report.ready/v1',token:token},'*');}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});
  else ready();
  document.addEventListener('click',function(event){
    const a=event.target.closest&&event.target.closest('a[data-published-member]');
    if(!a)return;
    event.preventDefault();event.stopImmediatePropagation();
    parent.postMessage({type:'upstate.published-report.member/v1',token:token,id:a.dataset.publishedMember},'*');
  },true);
  window.addEventListener('message',function(event){
    if(event.source!==parent||!event.data||event.data.token!==token)return;
    if(event.data.type==='upstate.published-report.print/v1')window.print();
  });
})();
</script>""".replace("TOKEN", json.dumps(token))


def prepare(operator, workspace_key, workspace, store, study_id, version_id, member):
    if not isinstance(version_id, str) or not version_id:
        raise ValueError("Choose the exact retained study edition")
    record = store._record(study_id, version_id)
    if record["study_id"] != study_id or record["version_id"] != version_id:
        raise ValueError("The selected retained study edition changed")
    if not isinstance(member, str) or member not in record["source_entries"]:
        raise ValueError("Choose a registered original report member")
    if PurePosixPath(member).suffix.lower() not in {".html", ".htm"}:
        raise ValueError("Choose an original HTML report")
    inventory = {entry["path"]: entry for entry in record["source_files"]}
    if len(inventory) != len(record["source_files"]):
        raise ValueError("The retained source inventory contains duplicate paths")
    paths = {}

    def original(name, limit):
        descriptor = inventory.get(name)
        if descriptor is None or name not in record["source_entries"]:
            raise ValueError("Original report member is not registered: " + name)
        if type(descriptor.get("bytes")) is not int or not 0 <= descriptor["bytes"] <= limit:
            raise ValueError("Original report member exceeds preview capacity: " + name)
        path, _ = store.source_file(study_id, name, version_id)
        with path.open("rb") as stream:
            raw = stream.read(limit + 1)
        if len(raw) != descriptor["bytes"] or hashlib.sha256(raw).hexdigest() != descriptor["sha256"]:
            raise ValueError("Original report member changed: " + name)
        paths[name] = path
        return raw

    raw = original(member, HTML_LIMIT)
    source, images = embed_images(raw.decode("utf-8-sig"), member, inventory, original)
    parser = _Companions(source, member, inventory, original)
    parser.feed(source)
    parser.close()
    for start, end, replacement in reversed(parser.edits):
        source = source[:start] + replacement + source[end:]
    identity = {
        "schema": "upstate.published-report-preview/v1", "version": VERSION,
        "project_id": workspace.project["id"], "workspace": workspace_key,
        "study_id": study_id, "version_id": version_id,
        "source_collection_id": record["source_collection_id"], "member": member,
        "source": inventory[member], "links": [
            {**row, "source": inventory[row["path"]]} for row in parser.links],
        "assets": {name: inventory[name] for name in sorted(set(paths) - {member})},
        "implementation_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    }
    token = hashlib.sha256(json.dumps(identity, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    bridge = _bridge(token)
    match = re.search(r"<head\b[^>]*>", source, flags=re.I)
    if match:
        source = source[:match.end()] + bridge + source[match.end():]
    else:
        match = re.match(r"\s*<!doctype[^>]*>", source, flags=re.I)
        position = match.end() if match else 0
        source = source[:position] + bridge + source[position:]
    body = source.encode("utf-8")
    digest = hashlib.sha256(body).hexdigest()
    directory = operator.root / "previews" / FOLDER
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / (digest + ".html")
    if target.exists():
        if target.read_bytes() != body:
            raise ValueError("Retained original-report preview differs")
    else:
        import os
        import tempfile
        with tempfile.NamedTemporaryFile(dir=directory, delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(body)
        try:
            os.replace(temporary, target)
        finally:
            temporary.unlink(missing_ok=True)
    description = {"path": target.relative_to(operator.root).as_posix(),
                   "bytes": len(body), "sha256": digest,
                   "filename": "original-study-report-preview.html"}
    ticket = operator._ticket(workspace_key, target, description, "original-study-report-preview.html")

    def download(name):
        # source_file verifies the unchanged source body's CAS before the ticket.
        path = paths.get(name)
        if path is None:
            path, _ = store.source_file(study_id, name, version_id)
        description = describe_file(workspace.root, path)
        if any(description[key] != inventory[name][key] for key in ("bytes", "sha256")):
            raise ValueError("Original report download differs from its retained inventory: " + name)
        description["filename"] = PurePosixPath(name).name
        return operator._ticket(workspace_key, path, description, PurePosixPath(name).name)

    links = [{**row, "source": inventory[row["path"]], "download_ticket": download(row["path"])}
             for row in parser.links]
    return {
        "schema": "upstate.published-report-preview/v1", "id": token,
        "workspace": workspace_key, "study_id": study_id, "version_id": version_id,
        "source_collection_id": record["source_collection_id"], "member": member,
        "source": inventory[member], "title": PurePosixPath(member).name,
        "preview": {**ticket, "url": "/api/file/published-study-preview/" + quote(workspace_key, safe="") + "/" + ticket["id"]},
        "download": download(member), "links": links, "embedded_images": images,
    }


def file_reply(operator, workspace_key, ticket_id):
    operator.ws(workspace_key)
    ticket_id = identifier(ticket_id)
    with operator.lock:
        original = operator.downloads.get(ticket_id)
        ticket = dict(original) if original else None
    if ticket is None or ticket.get("workspace") != workspace_key:
        raise ValueError("Choose the original report preview in its Workspace")
    path = Path(ticket["path"]).resolve(strict=True)
    parent = (operator.root / "previews" / FOLDER).resolve(strict=True)
    if (path.parent != parent or path.suffix != ".html" or
            ticket.get("filename") != "original-study-report-preview.html"):
        raise ValueError("This ticket is not an original-report preview")
    identifier(path.stem)
    return {key: value for key, value in ticket.items() if key != "path"}, POLICY

const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const copy=value=>JSON.parse(JSON.stringify(value));
const SANDBOX="allow-scripts allow-downloads allow-modals allow-popups allow-popups-to-escape-sandbox";
function downloadURL(ticket,workspace) {
  if(!ticket||ticket.workspace!==workspace||!/^[a-f0-9]{64}$/.test(ticket.id||"")||
     ticket.url!=="/api/file/"+ticket.id)throw Error("The original download belongs to another file or Workspace.");
  return ticket.url+"?download=1";
}
function previewURL(ticket,workspace) {
  if(!ticket||ticket.workspace!==workspace||!/^[a-f0-9]{64}$/.test(ticket.id||"")||
     ticket.url!=="/api/file/published-study-preview/"+encodeURIComponent(workspace)+"/"+ticket.id)
    throw Error("The report preview belongs to another file or Workspace.");
  return ticket.url;
}

export function createPublishedOriginalReports(host,options) {
  let node=null,events=null,request=null,serial=0,current=null,history=[],frame=null,binding=null;
  let loading=false,error="",status="",retry=null,frameTimer=null,framePending=false;
  const context=()=>options.context();
  const key=value=>value&&JSON.stringify([value.workspace,value.study_id,value.version_id,value.view]);
  const valid=mark=>Boolean(node)&&mark.serial===serial&&key(context())===mark.key&&
    host.getWorkspace()===mark.workspace;
  function mark() {
    const value=context();
    if(!value?.workspace||!value.study_id||!value.version_id||host.getWorkspace()!==value.workspace)
      throw Error("Open the retained original study edition first.");
    return {serial,key:key(value),workspace:value.workspace,study_id:value.study_id,version_id:value.version_id};
  }
  function clearFrame() {
    if(frameTimer!==null){clearTimeout(frameTimer);frameTimer=null;}
    framePending=false;
    if(frame) {frame.src="about:blank";frame.remove();frame=null;}
  }
  function close() {
    ++serial;request?.abort();request=null;clearFrame();current=null;binding=null;history=[];
    loading=false;error="";status="";retry=null;
    if(node){node.hidden=true;node.innerHTML="";}
  }
  function sync() {
    if(binding&&(key(context())!==binding.key||host.getWorkspace()!==binding.workspace))close();
  }
  function shell() {
    if(!node)return;
    node.hidden=false;
    node.innerHTML='<header class="ps-original-header"><div><h2>Original study report</h2>'+
      '<p data-original-title></p></div><button type="button" data-original-action="close">Close report</button></header>'+
      '<p class="ps-help">This report keeps its complete original observation scope. Its own filters are independent of the selected tables in the study desk.</p>'+
      '<div class="ps-actions"><button type="button" data-original-action="back">Previous report</button>'+
      '<button type="button" data-original-action="print">Print this report</button>'+
      '<button type="button" data-original-action="retry" hidden>Retry opening</button>'+
      '<a data-original-download download>Download original HTML</a>'+
      '<button type="button" data-original-action="export">Export complete study</button></div>'+
      '<p data-original-status role="status" aria-live="polite"></p>'+
      '<div class="ps-original-frame" data-original-frame></div>'+
      '<details data-original-sources><summary>Original companion files</summary><ul class="ps-source-list" data-original-links></ul></details>';
  }
  function render() {
    if(!node)return;
    if(!node.querySelector("[data-original-frame]"))shell();
    node.querySelector("[data-original-title]").textContent=current?.result.member||"Opening the exact retained source…";
    const message=node.querySelector("[data-original-status]");
    message.textContent=error||status||(loading?"Reading verified original report and companions…":"");
    message.classList.toggle("ps-original-error",Boolean(error));
    node.querySelector('[data-original-action="back"]').disabled=loading||!history.length;
    node.querySelector('[data-original-action="print"]').disabled=loading||!current||!frame;
    node.querySelector('[data-original-action="retry"]').hidden=!retry;
    node.querySelector('[data-original-action="retry"]').disabled=loading;
    node.querySelector('[data-original-action="export"]').disabled=loading||!current;
    const original=node.querySelector("[data-original-download]");
    original.hidden=!current;
    if(current)original.href=downloadURL(current.result.download,binding.workspace);
    else original.removeAttribute("href");
    const unique=new Map();
    for(const row of current?.result.links||[])if(!unique.has(row.path))unique.set(row.path,row);
    node.querySelector("[data-original-links]").innerHTML=[...unique.values()].map(row=>
      '<li>'+(row.html?'<button type="button" class="ps-link-button" data-original-member="'+esc(row.id)+'">Open '+esc(row.path)+'</button> · ':"")+
      '<a href="'+esc(downloadURL(row.download_ticket,binding.workspace))+'" download>Download '+esc(row.path)+'</a>'+
      '<span class="ps-help">'+Number(row.source.bytes).toLocaleString()+' bytes</span></li>').join("");
    node.querySelector("[data-original-sources]").hidden=!unique.size;
  }
  async function navigate(selection,{back=false,replace=false}={}) {
    sync();++serial;request?.abort();
    const opening=mark(),prior=current;
    binding=opening;loading=true;error="";status="";retry=null;clearFrame();render();
    const controller=new AbortController();request=controller;
    try {
      const result=await host.api("/api/published-studies/report-preview",{
        method:"POST",body:{workspace:opening.workspace,study_id:opening.study_id,
          version_id:opening.version_id,path:selection.path},signal:controller.signal});
      if(!valid(opening))return;
      if(result.workspace!==opening.workspace||result.study_id!==opening.study_id||
         result.version_id!==opening.version_id||result.member!==selection.path||
         !/^[a-f0-9]{64}$/.test(result.id||"")||!Array.isArray(result.links))
        throw Error("The returned report is not the requested retained study source.");
      const seen=new Set();
      for(const row of result.links) {
        if(typeof row.id!=="string"||seen.has(row.id)||typeof row.path!=="string"||
           typeof row.html!=="boolean"||typeof row.download!=="boolean")
          throw Error("The report companion binding is invalid.");
        seen.add(row.id);downloadURL(row.download_ticket,opening.workspace);
      }
      const url=new URL(previewURL(result.preview,opening.workspace),window.location.origin);
      if(selection.query) {
        const query=new URLSearchParams(selection.query);query.delete("download");url.search=query.toString();
      }
      if(selection.fragment)url.hash=selection.fragment;
      downloadURL(result.download,opening.workspace);
      if(back)history.pop();else if(prior&&!replace)history.push(copy(prior.selection));
      current={selection:copy(selection),result};frame=document.createElement("iframe");
      frame.title="Original study report: "+result.member;
      frame.setAttribute("sandbox",SANDBOX);frame.referrerPolicy="no-referrer";
      const openedFrame=frame;
      function failedFrame() {
        if(!valid(opening)||frame!==openedFrame||!framePending)return;
        clearFrame();loading=false;
        error="The original report did not confirm that it opened. Retry opening, or download the original HTML and complete study.";
        retry={selection:copy(selection),back:false,replace:true};render();
      }
      frame.addEventListener("error",failedFrame,{once:true});
      framePending=true;
      frameTimer=setTimeout(failedFrame,15000);
      frame.src=url.pathname+url.search+url.hash;
      node.querySelector("[data-original-frame]").append(frame);
      status="Opening the retained report…";
    } catch(exception) {
      if(valid(opening)&&exception?.name!=="AbortError") {
        error=exception.message||String(exception);
        // Keep the prior immutable report selection for retry/back navigation.
        current=prior;retry={selection:copy(selection),back,replace};render();
      }
    } finally {
      if(valid(opening)) {if(!framePending)loading=false;if(request===controller)request=null;render();}
    }
  }
  async function open(path) {
    if(typeof path!=="string"||!path)throw Error("Choose an original report.");
    close();shell();await navigate({path,query:"",fragment:""});
    if(node&&!error)node.scrollIntoView?.({block:"start",behavior:"smooth"});
  }
  function activate(row) {
    if(!current||!binding||!valid(binding)||loading)return;
    if(row.html&&!row.download) {
      const expected=binding;
      navigate({path:row.path,query:row.query||"",fragment:row.fragment||""}).catch(error=>{if(valid(expected))showError(error);});
    } else {
      const anchor=document.createElement("a");
      anchor.href=downloadURL(row.download_ticket,binding.workspace);
      anchor.download=row.path.split("/").pop();anchor.hidden=true;
      node.append(anchor);anchor.click();anchor.remove();
      status="Original download requested: "+row.path;render();
    }
  }
  function showError(exception) {
    if(!node)return;
    error=exception?.message||String(exception);render();host.toast(error);
  }
  function message(event) {
    sync();
    const value=event.data;
    if(!current||!frame||event.source!==frame.contentWindow||event.origin!=="null"||
       !binding||!valid(binding)||!value||value.token!==current.result.id)return;
    if(value.type==="upstate.published-report.ready/v1") {
      if(!framePending)return;
      if(frameTimer!==null){clearTimeout(frameTimer);frameTimer=null;}
      framePending=false;loading=false;error="";retry=null;
      status="Original report opened. Its companion links use the verified retained source files.";render();return;
    }
    if(loading||value.type!=="upstate.published-report.member/v1"||typeof value.id!=="string")return;
    const row=current.result.links.find(item=>item.id===value.id);
    if(row)activate(row);
  }
  function click(event) {
    const button=event.target.closest("button");
    if(!button||!node?.contains(button))return;
    sync();if(!node||node.hidden)return;
    const action=button.dataset.originalAction;
    if(action==="close"){close();return;}
    if(!binding||!valid(binding)||loading)return;
    if(button.dataset.originalMember!==undefined) {
      const row=current?.result.links.find(item=>item.id===button.dataset.originalMember);
      if(row)activate({...row,download:false});
    } else if(action==="back"&&history.length) {
      const expected=binding;
      navigate(history.at(-1),{back:true}).catch(error=>{if(valid(expected))showError(error);});
    } else if(action==="retry"&&retry) {
      const chosen=copy(retry),expected=binding;
      navigate(chosen.selection,{back:chosen.back,replace:chosen.replace}).catch(error=>{if(valid(expected))showError(error);});
    } else if(action==="print"&&frame&&current) {
      frame.contentWindow.postMessage({type:"upstate.published-report.print/v1",token:current.result.id},"*");
    } else if(action==="export"&&current) {
      const selected=copy({study_id:binding.study_id,version_id:binding.version_id});
      const expected=binding;
      Promise.resolve(options.exportComplete(selected)).catch(error=>{if(valid(expected))showError(error);});
    }
  }
  function mount(target) {
    detach();node=target;node.hidden=true;events=new AbortController();
    node.addEventListener("click",click,{signal:events.signal});
    window.addEventListener("message",message,{signal:events.signal});
  }
  function detach() {close();events?.abort();events=null;node=null;}
  return {mount,detach,sync,open};
}

