      const columns = [["site_id","Station"],["year","Year"],["month","Month"],["units","Unit"],["avg_daily_minimum","Avg daily min"],["avg_daily_maximum","Avg daily max"],["published_avg_daily_range","Published avg daily range"],["n_days","Days"]];
