.published-studies-desk{--ps-ink:#252a2f;--ps-muted:#5d656c;--ps-line:#cbd0d4;--ps-panel:#f5f6f7;--ps-strong:#343b42;color:var(--ps-ink);font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding:24px;min-width:0;max-width:1800px;margin:auto}
.published-studies-desk *{box-sizing:border-box}
.published-studies-desk h1{font-size:25px;line-height:1.2;margin:0 0 10px;font-weight:650}
.published-studies-desk h2{font-size:19px;line-height:1.3;margin:0 0 10px}
.published-studies-desk h3{font-size:15px;margin:0 0 8px}
.published-studies-desk p{margin:6px 0 12px;max-width:1000px}
.published-studies-desk button,.published-studies-desk input,.published-studies-desk select{font:inherit;border:1px solid #aeb6bd;border-radius:3px;background:white;color:var(--ps-ink);padding:7px 10px;min-height:36px}
.published-studies-desk button{cursor:pointer;font-weight:550;white-space:nowrap}
.published-studies-desk button:hover{background:#e9ecef;border-color:#7b858e}
.published-studies-desk button:disabled{cursor:default;opacity:.5}
.published-studies-desk :focus-visible{outline:2px solid #343b42;outline-offset:2px}
.published-studies-desk a{color:#303e4a;text-decoration:underline;text-underline-offset:2px}
.published-studies-desk label{display:flex;flex-direction:column;gap:5px;font-weight:550}
.published-studies-desk select,.published-studies-desk input{width:100%;font-weight:400;max-width:100%}
.published-studies-desk [hidden]{display:none!important}
.published-studies-desk summary{font-weight:600;cursor:pointer;padding:8px 0}
.published-studies-desk details{border-top:1px solid var(--ps-line);margin-top:10px;padding-top:6px}
.ps-header,.ps-study-control,.ps-builtin,.ps-detail-head{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}
.ps-header>div{max-width:1060px}
.ps-eyebrow{font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:var(--ps-muted);font-weight:650}
.ps-status{font-size:13px;min-height:24px;color:var(--ps-muted)}
.ps-status[data-error="true"]{font-weight:650;border-left:3px solid #4a5056;padding-left:10px}
.ps-intake,.ps-summary,.ps-filters,.ps-methods,.ps-visual,.ps-row-detail{border:1px solid var(--ps-line);background:white;padding:18px;margin:16px 0}
.ps-intake{background:var(--ps-panel)}
.ps-builtin{align-items:center}
.ps-builtin p{margin:4px 0 0}
.ps-form-grid,.ps-filter-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:12px 0}
.ps-wide{min-width:0}
.ps-help{font-size:12px;color:var(--ps-muted);font-weight:400}
.ps-study-control{align-items:flex-end;margin:22px 0 16px}
.ps-study-control>label{flex:1;max-width:850px;min-width:0}
.ps-actions{display:flex;flex-wrap:wrap;gap:8px}
.ps-counts{display:grid;grid-template-columns:repeat(5,minmax(100px,1fr));gap:0;border-top:1px solid var(--ps-line);border-bottom:1px solid var(--ps-line);margin:18px 0}
.ps-counts>div{padding:12px 15px;border-right:1px solid var(--ps-line)}
.ps-counts>div:last-child{border-right:none}
.ps-counts dt{font-size:12px;color:var(--ps-muted)}
.ps-counts dd{margin:2px 0 0;font-size:23px;line-height:1.3;font-variant-numeric:tabular-nums}
.ps-support{display:grid;grid-template-columns:1fr 1fr;gap:22px;font-size:13px}
.ps-filters{background:var(--ps-panel)}
.ps-filters fieldset{border:0;padding:0;margin:0 0 16px}
.ps-filters legend{font-weight:600;margin-bottom:8px}
.ps-filters [data-ps-sites]{display:flex;flex-wrap:wrap;gap:8px 22px}
.published-studies-desk .ps-check{display:flex;flex-direction:row;align-items:center;gap:7px;font-weight:400}
.published-studies-desk .ps-check input{width:16px;height:16px;min-height:16px;accent-color:#343b42;margin:0}
.ps-filter-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
.ps-tabs{display:flex;flex-wrap:wrap;border-bottom:1px solid var(--ps-line);gap:3px;margin-top:22px}
