.published-studies-desk th{font-weight:650;background:#e9ecef;position:sticky;top:0;z-index:1}
.published-studies-desk th,.published-studies-desk td{padding:8px 10px;border-right:1px solid #d9dde0;border-bottom:1px solid #d9dde0;vertical-align:top}
.published-studies-desk tr:last-child td{border-bottom:none}
.published-studies-desk th:last-child,.published-studies-desk td:last-child{border-right:none}
.published-studies-desk tbody tr:nth-child(even){background:#f6f7f8}
.published-studies-desk .ps-link-button{border:0;background:none;padding:0;min-height:0;font:inherit;text-decoration:underline;text-underline-offset:2px}
.ps-empty{padding:30px 20px;border:1px solid var(--ps-line);background:#f8f9fa}
.ps-empty-row{padding:15px;background:#f5f6f7;color:var(--ps-muted)}
.ps-source-list{padding:0;list-style:none}
.ps-source-list li{display:flex;justify-content:space-between;gap:20px;padding:7px 0;border-bottom:1px solid #e2e5e8}
.ps-visual img{max-width:100%;height:auto;border:1px solid var(--ps-line);margin:12px 0}
.ps-source-notes article{padding:14px 0;border-top:1px solid #e2e5e8}
.ps-source-notes p{font-size:13px}
.ps-row-detail{background:#f5f6f7;overflow:auto}
.ps-raw-cells{display:grid;grid-template-columns:minmax(150px,240px) minmax(0,1fr);font-size:12px}
.ps-raw-cells dt,.ps-raw-cells dd{padding:6px 10px;margin:0;border-bottom:1px solid #d9dde0;overflow-wrap:anywhere}
.ps-raw-cells dt{font-weight:600}
@media(max-width:1000px){.ps-header,.ps-study-control{flex-direction:column;align-items:stretch}.ps-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ps-counts{grid-template-columns:repeat(3,minmax(90px,1fr))}.ps-support{grid-template-columns:1fr;gap:4px}}
@media(max-width:600px){.published-studies-desk{padding:14px}.ps-form-grid,.ps-filter-grid{grid-template-columns:1fr}.ps-builtin{flex-direction:column;align-items:stretch}.ps-counts{grid-template-columns:repeat(2,minmax(90px,1fr))}.ps-source-list li{flex-direction:column;gap:2px}.ps-raw-cells{grid-template-columns:1fr}.ps-raw-cells dt{border-bottom:0;padding-bottom:0}}

.ps-reviews{border:1px solid var(--ps-line);background:var(--ps-panel);padding:18px;margin:16px 0}
.ps-review-open{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap}
.ps-review-open>label{flex:1;min-width:220px}
.ps-reviews form[data-ps-review-editor]{display:grid;gap:12px;margin-top:14px}
.published-studies-desk textarea{font:inherit;border:1px solid #aeb6bd;border-radius:3px;background:white;color:var(--ps-ink);padding:8px 10px;width:100%;resize:vertical;min-height:90px}
.ps-review-binding{display:grid;grid-template-columns:140px minmax(0,1fr);font-size:12px;margin:10px 0}
.ps-review-binding dt,.ps-review-binding dd{padding:5px 8px;margin:0;border-bottom:1px solid var(--ps-line);overflow-wrap:anywhere}
.ps-review-binding dt{font-weight:600}
.ps-review-selection{overflow-wrap:anywhere}
.ps-review-notice{border-left:3px solid var(--ps-strong);padding-left:10px}
.ps-review-snapshot{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;font-size:12px;padding:12px;background:white;border:1px solid var(--ps-line)}
.ps-filter-grid select[multiple]{min-height:104px}
.ps-filter-grid label>.ps-link-button{align-self:flex-start;font-size:12px;font-weight:400}
@media(max-width:600px){.ps-review-open{align-items:stretch;flex-direction:column}.ps-review-open>label{min-width:0;width:100%}.ps-review-binding{grid-template-columns:1fr}.ps-review-binding dt{border-bottom:0;padding-bottom:0}}

/* Original retained reports keep their own opaque script context. */
.published-studies-desk .ps-original-report{border:1px solid var(--ps-line);padding:18px;margin:20px 0;background:#fff;min-width:0}
.published-studies-desk .ps-original-header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;min-width:0}
.published-studies-desk .ps-original-header p{overflow-wrap:anywhere;margin-bottom:8px}
.published-studies-desk .ps-original-report .ps-actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.published-studies-desk .ps-original-frame{width:100%;min-width:0;margin:12px 0;border:1px solid var(--ps-line);background:#fff}
.published-studies-desk .ps-original-frame:empty{display:none}
.published-studies-desk .ps-original-frame iframe{display:block;width:100%;height:78vh;min-height:420px;border:0;background:#fff}
.published-studies-desk .ps-original-report .ps-original-error{font-weight:600;border-left:3px solid var(--ps-strong);padding:8px 12px;background:var(--ps-panel)}
.published-studies-desk .ps-original-report .ps-source-list{overflow-wrap:anywhere}
@media(max-width:600px){.published-studies-desk .ps-original-report{padding:12px}.published-studies-desk .ps-original-header{display:block}.published-studies-desk .ps-original-header>button{margin-bottom:10px}.published-studies-desk .ps-original-report button{white-space:normal}.published-studies-desk .ps-original-frame iframe{height:74vh;min-height:360px}}
@media print{.published-studies-desk .ps-original-report{display:none}}

